</main></div><div id="toast" class="toast"></div><script>const CSRF=<?=json_encode($csrf)?>;async function api(action,data={}){const fd=new FormData();fd.append('action',action);for(const [k,v] of Object.entries(data))fd.append(k,v??'');const r=await fetch('api.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':CSRF},credentials:'same-origin'});return await r.json()}function toast(t,ok=true){const e=document.querySelector('#toast');e.textContent=t;e.className='toast show';e.style.borderColor=ok?'rgba(69,223,160,.35)':'rgba(255,102,120,.35)';setTimeout(()=>e.className='toast',3000)}</script></body></html>
